// High School course unit (docs/design/COURSES.md, docs/design/COURSE_QUALITY.md): English 9, Unit 2, Reading Informational Texts.
// Our own wording and questions, written to the named national standards the course follows: the Common Core State
// Standards for English Language Arts, Reading: Informational Text, grades 9-10 (RI.9-10.1 to 9-10.9; RI.9-10.10, the range
// of reading, is met by the variety of the passages). Nine outline topics, one skill each: citing strong textual evidence
// (1), central idea and objective summary (2), a series of ideas or events (3), word meaning, technical and figurative (4),
// how an author develops a claim across sentences, paragraphs and sections (5), point of view, purpose and rhetoric (6),
// accounts in different mediums (7), delineating and evaluating an argument, valid reasoning and fallacies (8), and seminal
// U.S. documents (9). Every passage is either a few lines from a U.S. document or an American writer who died long ago, given
// with author, title and date and checked against the lines as printed (spelling and capitals as in common printings; the
// lines are only ever quoted, never altered, and a mid-sentence cut is marked in the label), or labelled "Fictional passage"
// and written for this unit; nothing is quoted from a copyrighted text, and no passage is reused from another unit. A
// question asks about the words on the page: the answer is in the passage or is a standard term of the course. Every
// question offers lettered choices in its prompt and takes the letter (or the choice's own words); the right letter moves.
const tab=(title,rows,cols=['Value'])=>({t:'setups',title,head:'',rows,cols});
/* Video pictures: figure coordinates use a 100 x 34 sketch, north/up. Flow arrows trace before labels appear. */
const sketch=(title,regions,notes=[])=>{const pts={},polys=[];regions.forEach(([label,xy,col=0],i)=>{const v=xy.map(([x,y],k)=>{const n=String.fromCharCode(65+k)+i;pts[n]=[x,y];return n;}).join('');polys.push({v,label,col});});return {t:'figure',title,view:[0,100,0,34],pts,polys,notes:notes.map(([x,y,text])=>({at:[x,y],text})),dots:'',hide:Object.keys(pts).join('')};};
const flow=(title,stages)=>{const q=sketch(title,stages.map(([label],i)=>[label,[[i*36,13],[i*36+28,13],[i*36+28,25],[i*36,25]],i]),stages.map(([,detail],i)=>[i*36+14,7,detail]));q.segs=[];for(let i=0;i<2;i++){q.pts['P'+i]=[i*36+29,19];q.pts['Q'+i]=[i*36+35,19];q.segs.push({v:`P${i}Q${i}`,arrows:1,col:i,w:2});}q.hide=Object.keys(q.pts).join('');return q;};
const board=(title,lines,why)=>({t:'board',title,lines,...(why?{why}:{})});
const pass=(title,texts,small=true)=>({t:'passages',title,texts,...(small?{small:true}:{})});
const L='ABCDEF';
/* lettered choices, the right one moved to position k: returns {text, letter} */
const dot=o=>o.replace(/\.$/,'');
const choose=(right,wrong,k)=>{right=dot(right);const opts=wrong.map(dot);opts.splice(k%(wrong.length+1),0,right);return {text:opts.map((o,i)=>`${L[i]}: ${o}`).join(', '),letter:L[opts.indexOf(right)],n:opts.length};};
const ask=n=>n===2?'Answer A or B.':n===3?'Answer A, B or C.':`Answer ${[...L.slice(0,n-1)].join(', ')} or ${L[n-1]}.`;
